        }
		
		private void BuildSearchFieldsGenerated(PriceStepPM entityPM, PriceStep entityPOCO, bool isNewEntity)
        {
            string mySearchFields = "";
			
           
            entityPM.SearchFields += mySearchFields;
            entityPOCO.SearchFields += mySearchFields;
        }
			  
